def digital_root(n: int) -> int:
    """Compute the digital root using the O(1) formula: 1 + (n - 1) % 9."""
    if n == 0:
        return 0
    return 1 + (n - 1) % 9


def digital_root_steps(n: int) -> list[int]:
    """Show each intermediate sum in the digital root process."""
    steps = [n]
    while n >= 10:
        n = sum(int(d) for d in str(n))
        steps.append(n)
    return steps


if __name__ == "__main__":
    for num in [0, 9, 10, 99, 123, 9999, 65536, 123456789]:
        steps = digital_root_steps(num)
        print(f"{num:>12} -> {' -> '.join(map(str, steps))}  (root={steps[-1]})")
